<?php
session_start();require_once '../config/database.php';require_once 'lib.php';require_once 'assignment_service.php';if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);die('POST required.');}
try{ttOperationsRequireCsrf();$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$railroadId=(int)$railroad['id'];$id=(int)($_POST['assignment_id']??0);$pdo->beginTransaction();$stmt=$pdo->prepare('SELECT a.*,s.status session_status FROM operation_assignments a JOIN operating_sessions s ON s.id=a.session_id AND s.railroad_id=a.railroad_id WHERE a.id=? AND a.railroad_id=? FOR UPDATE');$stmt->execute([$id,$railroadId]);$a=$stmt->fetch(PDO::FETCH_ASSOC);if(!$a)throw new RuntimeException('Assignment not found.');$statuses=ttAssignmentListStatuses($pdo,$id,$railroadId);if(!ttAssignmentIsEditable($a,$statuses))throw new RuntimeException('This assignment cannot be deleted because approved, active, completed, cancelled, or historical work must be retained.');if(array_diff($statuses,['draft','cancelled']))throw new RuntimeException('Only unapproved draft switch-list revisions can be removed with an assignment.');$stmt=$pdo->prepare("SELECT assignment_number FROM operation_assignments WHERE predecessor_assignment_id=? AND railroad_id=? LIMIT 1");$stmt->execute([$id,$railroadId]);if($dependent=$stmt->fetchColumn())throw new RuntimeException('Delete or update dependent assignment '.$dependent.' first.');if($a['prepared_cut_id'])$pdo->prepare("UPDATE prepared_cuts SET status='ready' WHERE id=? AND railroad_id=? AND status='assigned'")->execute([(int)$a['prepared_cut_id'],$railroadId]);$pdo->prepare("DELETE m FROM operation_switch_list_moves m JOIN operation_switch_lists sl ON sl.id=m.switch_list_id WHERE sl.assignment_id=? AND sl.railroad_id=? AND sl.status IN('draft','cancelled')")->execute([$id,$railroadId]);$pdo->prepare("DELETE FROM operation_switch_lists WHERE assignment_id=? AND railroad_id=? AND status IN('draft','cancelled')")->execute([$id,$railroadId]);$pdo->prepare('DELETE FROM operation_assignment_locomotives WHERE assignment_id=?')->execute([$id]);$pdo->prepare('DELETE FROM operation_assignment_starting_cars WHERE assignment_id=?')->execute([$id]);$pdo->prepare('DELETE FROM operation_assignments WHERE id=? AND railroad_id=?')->execute([$id,$railroadId]);$pdo->commit();header('Location: session_edit.php?id='.(int)$a['session_id']);exit;}catch(Throwable$e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();http_response_code(409);die(ttHtml($e->getMessage()));}
